parameters.jsonBody:
={{ JSON.stringify({
  origen: ($json.execution && ($json.execution.lastNodeExecuted || ($json.execution.error && $json.execution.error.node && $json.execution.error.node.name))) || 'n8n',
  error_type: ($json.execution && $json.execution.error && ($json.execution.error.name || $json.execution.error.constructor && $json.execution.error.constructor.name)) || 'n8n_error',
  mensaje: ($json.execution && $json.execution.error && $json.execution.error.message) || 'Fallo en workflow de Tommy',
  severidad: 'ERROR',
  workflow: ($json.workflow && $json.workflow.name) || '',
  execution_url: ($json.execution && $json.execution.url) || '',
  detalle: {
    node_error: ($json.execution && $json.execution.error && $json.execution.error.node && $json.execution.error.node.name) || '',
    stack: ($json.execution && $json.execution.error && $json.execution.error.stack ? String($json.execution.error.stack).slice(0, 1200) : ''),
    mode: ($json.execution && $json.execution.mode) || '',
    execution_id: ($json.execution && $json.execution.id) || ''
  }
}) }}
